INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Hardware > Auswahl und Komponenten > Fehlerbehebung > Verbindungsprobleme
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Verbindungsprobleme immer durch einen Hardwaredefekt verursacht sein?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software oder Konfiguration können Ursachen sein"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich Hardware"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Fehlerbehebung von Verbindungsproblemen immer alle Kabel überprüft werden?', 2, '[{"text": "Ja", "correct": true, "because": "Defekte Kabel sind häufige Ursachen"}, {"text": "Nein", "correct": false, "because": "Überprüfung ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Neustart des Systems immer die erste Maßnahme bei Verbindungsproblemen?', 2, '[{"text": "Nein", "correct": true, "because": "Prüfung der physischen Verbindungen kann zuerst nötig sein"}, {"text": "Ja", "correct": false, "because": "Nicht immer primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Verbindungsprobleme durch fehlerhafte Treiber verursacht werden?', 2, '[{"text": "Ja", "correct": true, "because": "Treiber steuern Hardwarekommunikation"}, {"text": "Nein", "correct": false, "because": "Treiber sind oft Ursache"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Verbindungsprobleme immer sofort nach dem Auftreten sichtbar?', 2, '[{"text": "Nein", "correct": true, "because": "Manche Probleme treten intermittierend auf"}, {"text": "Ja", "correct": false, "because": "Nicht immer offensichtlich"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme ist bei Verbindungsproblemen als erstes sinnvoll?', 3, '[{"text": "Überprüfung der Kabelverbindungen", "correct": true, "because": "Physische Probleme sind häufig"}, {"text": "Neuinstallation des Betriebssystems", "correct": false, "because": "Zu aufwendig als Erstes"}, {"text": "Austausch der Hardware", "correct": false, "because": "Teuer und nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft bei der Diagnose von Netzwerkverbindungsproblemen?', 2, '[{"text": "Ping", "correct": true, "because": "Testet Erreichbarkeit im Netzwerk"}, {"text": "Multimeter", "correct": false, "because": "Für elektrische Tests"}, {"text": "Schraubendreher", "correct": false, "because": "Physische Reparatur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponente wird bei USB-Verbindungsproblemen zuerst überprüft?', 2, '[{"text": "USB-Kabel", "correct": true, "because": "Häufige Fehlerquelle"}, {"text": "Prozessor", "correct": false, "because": "Nicht direkt relevant"}, {"text": "Netzteil", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ursache ist bei WLAN-Verbindungsproblemen am häufigsten?', 3, '[{"text": "Signalstörungen", "correct": true, "because": "Interferenzen beeinträchtigen Verbindung"}, {"text": "Defekter Prozessor", "correct": false, "because": "Unwahrscheinlich"}, {"text": "Falsches Betriebssystem", "correct": false, "because": "Weniger wahrscheinlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt hilft bei der Fehlerbehebung von Verbindungsproblemen?', 2, '[{"text": "Treiber aktualisieren", "correct": true, "because": "Behebt Softwareprobleme"}, {"text": "Monitor ausschalten", "correct": false, "because": "Irrelevant"}, {"text": "Festplatte formatieren", "correct": false, "because": "Zu drastisch"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei der Fehlerbehebung von Verbindungsproblemen üblich?', 4, '[{"text": "Kabel überprüfen", "correct": true, "because": "Physische Fehler ausschließen"}, {"text": "Treiber aktualisieren", "correct": true, "because": "Softwareprobleme lösen"}, {"text": "Netzwerkverbindung testen", "correct": true, "because": "Diagnose der Verbindung"}, {"text": "Monitor reinigen", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ursachen können Verbindungsprobleme haben?', 3, '[{"text": "Defekte Kabel", "correct": true, "because": "Physische Schäden"}, {"text": "Falsche Treiber", "correct": true, "because": "Softwarefehler"}, {"text": "Signalstörungen", "correct": true, "because": "Bei drahtlosen Verbindungen"}, {"text": "Leere Tintenpatrone", "correct": false, "because": "Druckerproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werkzeuge helfen bei der Diagnose von Verbindungsproblemen?', 3, '[{"text": "Ping", "correct": true, "because": "Testet Netzwerkerreichbarkeit"}, {"text": "ipconfig", "correct": true, "because": "Zeigt Netzwerkkonfiguration"}, {"text": "tracert", "correct": true, "because": "Verfolgt Datenpfad"}, {"text": "Texteditor", "correct": false, "because": "Nicht technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Symptome deuten auf Verbindungsprobleme hin?', 4, '[{"text": "Keine Internetverbindung", "correct": true, "because": "Klarer Hinweis"}, {"text": "Langsame Datenübertragung", "correct": true, "because": "Zeigt Störung"}, {"text": "Fehlende Geräteerkennung", "correct": true, "because": "Verbindung fehlt"}, {"text": "Hoher Stromverbrauch", "correct": false, "because": "Unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen können Verbindungsprobleme lösen?', 3, '[{"text": "Kabel austauschen", "correct": true, "because": "Behebt physische Defekte"}, {"text": "Router neu starten", "correct": true, "because": "Löst temporäre Störungen"}, {"text": "Treiber neu installieren", "correct": true, "because": "Korrigiert Softwarefehler"}, {"text": "Monitor kalibrieren", "correct": false, "because": "Irrelevant"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Verbindungsprobleme können durch defekte Kabel entstehen. b) Ein Neustart löst immer alle Verbindungsprobleme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kabel ja, Neustart nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ping testet die Netzwerkverbindung. b) Verbindungsprobleme sind immer hardwarebedingt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ping ja, Ursachen vielfältig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Treiberprobleme können Verbindungsprobleme verursachen. b) Kabelüberprüfung ist bei WLAN-Problemen unnötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Treiber ja, Kabel bei WLAN relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Signalstörungen beeinträchtigen WLAN-Verbindungen. b) Ein defekter Prozessor ist die häufigste Ursache für Verbindungsprobleme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Störungen ja, Prozessor selten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Router-Neustart kann Verbindungsprobleme beheben. b) Verbindungsprobleme sind immer sofort erkennbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Neustart ja, Probleme oft subtil"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

